generated_sql:
SELECT DATE(payment_date) AS rental_date, AVG(amount) AS average_daily_revenue
FROM payment
GROUP BY DATE(payment_date);

SELECT COUNT(*) 
FROM customer 
WHERE email LIKE '%gmail%';

SELECT COUNT(*) 
FROM customer 
WHERE customer_id NOT IN (SELECT DISTINCT customer_id FROM rental);

SELECT COUNT(DISTINCT rental.customer_id) 
FROM rental 
WHERE EXTRACT(DOW FROM rental.rental_date) IN (6, 0);

SELECT COUNT(*) 
FROM rental 
WHERE return_date IS NULL;

SELECT COUNT(*) 
FROM film 
WHERE rental_duration >= 7;

SELECT COUNT(*) 
FROM film 
WHERE title ILIKE '%LOVE%';

SELECT COUNT(*) 
FROM film 
WHERE length >= 120;

SELECT COUNT(DISTINCT city) 
FROM store 
WHERE address_id IN (SELECT address_id FROM address WHERE city IN (SELECT city FROM city WHERE country_id = (SELECT country_id FROM country WHERE country = 'United States')));

SELECT COUNT(*) 
FROM store 
WHERE store_id NOT IN (SELECT DISTINCT store_id FROM rental);

SELECT EXTRACT(DOW FROM r.rental_date) AS day_of_week, COUNT(r.rental_id) AS average_rentals
FROM rental r
GROUP BY day_of_week;

SELECT COUNT(*) 
FROM film 
WHERE rental_rate = 0.99;

SELECT COUNT(*) 
FROM film 
WHERE rental_rate > 2.99;

SELECT COUNT(*) 
FROM film 
WHERE replacement_cost >= 20;

SELECT COUNT(*) 
FROM film 
WHERE rental_rate > (SELECT AVG(rental_rate) FROM film);

SELECT COUNT(*) 
FROM film 
WHERE special_features LIKE '%Deleted Scenes%';

SELECT COUNT(*) 
FROM inventory 
WHERE inventory.film_id IN (SELECT film.id FROM film);

SELECT COUNT(*) 
FROM film 
WHERE length > (SELECT AVG(length) FROM film);
